input.command:
for f in 01 02 03 04 05; do
  echo "=== norm$f.txt: rotation-pattern violations (system/status must match case position mod 4) ==="
  tr -d '\r' < .scratch-t04/norm$f.txt | awk '
  {
    n = $1; sub(/.*-/, "", n); n = n + 0;
    pos = ((n - 1) % 4);
    expect_sys = (pos==0?"linux-x86_64":pos==1?"windows-x86_64":pos==2?"freebsd-x86_64":"macos-arm64");
    expect_stat = (pos==0?"review":pos==1?"recorded":pos==2?"follow-up":"supported");
    if ($2 != expect_sys || $3 != expect_stat) print "MISMATCH:", $0;
  }' | wc -l
done

