for f in 01 02 03 04 05; do
  case $f in
    01) src=maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-01.md; ids=$(grep -o 'audit-v2-s06-t13-[0-9]\{6\}' "$src") ;;
    02) src=maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-02.jsonl; ids=$(grep -o '"case": "audit-v2-s06-t13-[0-9]\{6\}"' "$src" | grep -o 'audit-v2-s06-t13-[0-9]\{6\}') ;;
    03) src=maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-03.csv; ids=$(awk -F',' 'NR>1{gsub(/"/,"",$1); print $1}' "$src") ;;
    04) src=maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-04.yaml; ids=$(grep -o '^- case: audit-v2-s06-t13-[0-9]\{6\}' "$src" | grep -o 'audit-v2-s06-t13-[0-9]\{6\}') ;;
    05) src=maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-05.log; ids=$(grep -o '^case=audit-v2-s06-t13-[0-9]\{6\}' "$src" | grep -o 'audit-v2-s06-t13-[0-9]\{6\}') ;;
  esac
  dupes=$(echo "$ids" | sort | uniq -d)
  echo "file-$f duplicate-count=$(echo -n "$dupes" | grep -c . )"
done

grep -o 'System: [a-z0-9_-]*' maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-01.md | sed 's/System: //' > .scratch-t13/sys-01.txt
grep -o 'Status: [a-z-]*' maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-01.md | sed 's/Status: //' > .scratch-t13/status-01.txt
awk '{a[NR%4]=$0} END{}' .scratch-t13/sys-01.txt
awk 'NR==1{first=$0} { expect = (NR-1)%4; } { print }' .scratch-t13/sys-01.txt | awk '
{
  cyc[(NR-1)%4]=(cyc[(NR-1)%4]==""?$0:cyc[(NR-1)%4]);
  if (cyc[(NR-1)%4] != $0) { print "VIOLATION at line " NR ": " $0; bad=1 }
}
END { if (!bad) print "system rotation OK, cycle=" cyc[0] "," cyc[1] "," cyc[2] "," cyc[3] }
' 
awk '
{
  cyc[(NR-1)%4]=(cyc[(NR-1)%4]==""?$0:cyc[(NR-1)%4]);
  if (cyc[(NR-1)%4] != $0) { print "VIOLATION at line " NR ": " $0; bad=1 }
}
END { if (!bad) print "status rotation OK, cycle=" cyc[0] "," cyc[1] "," cyc[2] "," cyc[3] }
' .scratch-t13/status-01.txt

awk '
/^- case: / { case_id=$3 }
/^  system: / { sys=$2 }
/^  status: / { status=$2; print case_id","sys","status }
' maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-04.yaml > .scratch-t13/tuples-04.txt
wc -l < .scratch-t13/tuples-04.txt
head -2 .scratch-t13/tuples-04.txt

awk -F'"' '
{
  case_id=""; sys=""; status="";
  for(i=1;i<=NF;i++){
    if($i=="case") case_id=$(i+2);
    if($i=="system") sys=$(i+2);
    if($i=="status") status=$(i+2);
  }
  print case_id","sys","status;
}' maintenance/inputs/audit-v2-s06/ingress-operator-checklist/audit-v2-s06-t13-evidence-02.jsonl > .scratch-t13/tuples-02.txt
wc -l < .scratch-t13/tuples-02.txt
