awk '{cyc[(NR-1)%4]=(cyc[(NR-1)%4]==""?$0:cyc[(NR-1)%4]); if(cyc[(NR-1)%4]!=$0){print "VIOLATION line " NR; bad=1}} END{if(!bad) print "status rotation OK, cycle=" cyc[0] "," cyc[1] "," cyc[2] "," cyc[3]}' .scratch-t14/status-02.txt

